//! Replays `testdata/port/ingest/barcode.json`, generated by the real Go
//! `TestPortIngestBarcodeContract`: `DetectBarcode` over gozxing-generated,
//! degraded and photographed images, and `ScanPDFForBarcodes` /
//! `SplitPDFByBarcode` against fake pdftoppm/qpdf scripts (stored in the
//! fixture). Decoded text and format, separator pages, part names and bodies,
//! error text, tool transcript and output-directory leftovers must match Go.
#![cfg(unix)]

use base64::Engine as _;
use regex::Regex;
use serde::Deserialize;
use std::collections::BTreeMap;
use std::os::unix::fs::PermissionsExt;
use std::path::Path;
use std::sync::Mutex;
use symdesk_ingest::barcode::{
    BarcodeConfig, detect_barcode_bytes, scan_pdf_for_barcodes, split_pdf_by_barcode,
};

/// `PATH` and `TMPDIR` are process-global; scenarios run one at a time.
static ENV_LOCK: Mutex<()> = Mutex::new(());

#[derive(Deserialize)]
struct DetectCase {
    id: String,
    origin: String,
    data_b64: String,
    text: String,
    format: String,
    error: String,
}

#[derive(Deserialize, Clone)]
struct Scenario {
    id: String,
    pattern: String,
    discard: bool,
    parse_asn: bool,
    pages: BTreeMap<String, String>,
    npages: String,
    tools: String,
    scan_only: bool,
}

#[derive(Deserialize, Clone)]
struct SplitCase {
    scenario: Scenario,
    separator_pages: Vec<i64>,
    parts: Vec<String>,
    part_bodies: Vec<String>,
    asns: BTreeMap<String, i64>,
    errors: BTreeMap<String, String>,
    error: String,
    transcript: Vec<String>,
    leftovers: Vec<String>,
}

#[derive(Deserialize)]
struct Fixture {
    schema_version: u32,
    scripts: BTreeMap<String, String>,
    detect: Vec<DetectCase>,
    split: Vec<SplitCase>,
}

fn fixture() -> Fixture {
    let f: Fixture = serde_json::from_slice(
        &std::fs::read(
            Path::new(env!("CARGO_MANIFEST_DIR")).join("../../testdata/port/ingest/barcode.json"),
        )
        .unwrap(),
    )
    .unwrap();
    assert_eq!(f.schema_version, 1);
    f
}

fn b64(s: &str) -> Vec<u8> {
    base64::engine::general_purpose::STANDARD.decode(s).unwrap()
}

/// Images gozxing cannot decode but rxing can (declared limit: the Rust
/// decoder is a superset of the Go one on this corpus).
const RXING_SUPERSET: &[&str] = &["testdata/datamatrix/testdata/03.png"];

#[test]
fn detection_matches_go_over_the_whole_corpus() {
    let f = fixture();
    assert!(f.detect.len() >= 120, "corpus shrank: {}", f.detect.len());
    let mut decoded = 0;
    let mut mismatches = Vec::new();
    let mut superset = 0;
    for case in &f.detect {
        assert_eq!(case.error, "", "{}: Go reported an error", case.id);
        let (text, format) = detect_barcode_bytes(&b64(&case.data_b64)).unwrap();
        if !case.text.is_empty() {
            decoded += 1;
        }
        if (text.as_str(), format.as_str()) != (case.text.as_str(), case.format.as_str()) {
            // Declared: rxing recovers a payload where gozxing gives up. Rust
            // may decode strictly more, never differently or less.
            if case.text.is_empty() && RXING_SUPERSET.contains(&case.id.as_str()) {
                superset += 1;
                continue;
            }
            mismatches.push(format!(
                "{} [{}]: go ({:?}, {}) rust ({:?}, {})",
                case.id, case.origin, case.text, case.format, text, format
            ));
        }
    }
    assert_eq!(
        superset,
        RXING_SUPERSET.len(),
        "declared superset cases must still differ"
    );
    assert!(decoded >= 40, "too few Go decodes: {decoded}");
    assert!(
        mismatches.is_empty(),
        "{} of {} detection cases differ:\n{}",
        mismatches.len(),
        f.detect.len(),
        mismatches.join("\n")
    );
}

#[test]
fn detection_negative_control_a_mutated_expectation_is_caught() {
    let f = fixture();
    let case = f
        .detect
        .iter()
        .find(|c| c.id == "qr-patch/png")
        .expect("qr-patch/png");
    let (text, format) = detect_barcode_bytes(&b64(&case.data_b64)).unwrap();
    assert_eq!(text, "PATCH-T separator");
    assert_eq!(format, "QR_CODE");
    let mut tampered = b64(&case.data_b64);
    let last = tampered.len() / 2;
    for byte in &mut tampered[last..last + 64] {
        *byte ^= 0xff;
    }
    let outcome = detect_barcode_bytes(&tampered);
    assert!(
        outcome.map_or(true, |(t, _)| t != "PATCH-T separator"),
        "a corrupted image must not decode to the original text"
    );
}

fn write(dir: &Path, name: &str, content: &[u8], mode: u32) {
    let p = dir.join(name);
    std::fs::create_dir_all(p.parent().unwrap()).unwrap();
    std::fs::write(&p, content).unwrap();
    std::fs::set_permissions(&p, std::fs::Permissions::from_mode(mode)).unwrap();
}

fn run(f: &Fixture, case: &SplitCase) -> Vec<String> {
    let sc = &case.scenario;
    let _guard = ENV_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let root = tempdir();
    let (dir, out, tmp) = (root.join("tools"), root.join("out"), root.join("tmp"));
    for d in [&dir, &out, &tmp] {
        std::fs::create_dir_all(d).unwrap();
    }
    std::fs::create_dir_all(dir.join("img")).unwrap();
    for (name, data) in &sc.pages {
        write(&dir.join("img"), name, &b64(data), 0o600);
    }
    if sc.tools != "no-pdftoppm" {
        write(&dir, "pdftoppm", f.scripts["pdftoppm"].as_bytes(), 0o755);
    }
    if sc.tools != "no-qpdf" {
        write(&dir, "qpdf", f.scripts["qpdf"].as_bytes(), 0o755);
    }
    match sc.tools.as_str() {
        "pdftoppm-fails" => {
            write(&dir, "pdftoppm.exit", b"3", 0o644);
            write(&dir, "pdftoppm.err", b"Syntax Error: boom\n", 0o644);
        }
        "check-fails" => {
            write(&dir, "check.exit", b"2", 0o644);
            write(&dir, "check.err", b"qpdf: damaged\n", 0o644);
        }
        _ => {}
    }
    let n = if sc.npages == "zero" { "0" } else { &sc.npages };
    write(&dir, "npages", format!("{n}\n").as_bytes(), 0o644);
    write(&dir, "log", b"", 0o644);
    let input = dir.join("in.pdf");
    std::fs::write(&input, b"%PDF-fake").unwrap();
    // SAFETY: serialized by ENV_LOCK; no other thread reads the environment
    // concurrently in this test binary.
    unsafe {
        std::env::set_var("PATH", &dir);
        std::env::set_var("TMPDIR", &tmp);
    }
    let cfg = BarcodeConfig {
        separator_pattern: sc.pattern.clone(),
        discard_separators: sc.discard,
        parse_asn: sc.parse_asn,
        asn_prefix: "ASN:".into(),
    };
    let norm = |s: &str| -> String {
        let s = s
            .replace(out.to_str().unwrap(), "$OUT")
            .replace(dir.to_str().unwrap(), "$DIR")
            .replace(tmp.to_str().unwrap(), "$TMP");
        let s = Regex::new("symdesk-barcode-[0-9]+")
            .unwrap()
            .replace_all(&s, "symdesk-barcode-N")
            .into_owned();
        Regex::new(r"\.symdesk-pdf-[0-9A-Za-z-]+")
            .unwrap()
            .replace_all(&s, ".symdesk-pdf-N")
            .into_owned()
    };
    let (mut sep, mut parts, mut bodies, mut error) = (vec![], vec![], vec![], String::new());
    if sc.scan_only {
        match scan_pdf_for_barcodes(input.to_str().unwrap(), &cfg) {
            Ok(p) => sep = p,
            Err(e) => error = norm(&e),
        }
    } else {
        match split_pdf_by_barcode(input.to_str().unwrap(), &cfg, out.to_str().unwrap()) {
            Ok(r) => {
                sep = r.separator_pages;
                for p in r.parts {
                    bodies.push(String::from_utf8_lossy(&std::fs::read(&p).unwrap()).into_owned());
                    parts.push(norm(&p));
                }
                assert!(r.asns.is_empty(), "{}: Go never records ASNs", sc.id);
            }
            Err(e) => error = norm(&e),
        }
    }
    let transcript: Vec<String> = std::fs::read_to_string(dir.join("log"))
        .unwrap()
        .lines()
        .filter(|l| !l.is_empty())
        .map(norm)
        .collect();
    let mut leftovers: Vec<String> = std::fs::read_dir(&out)
        .unwrap()
        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
        .collect();
    leftovers.sort();
    let leaked: Vec<_> = std::fs::read_dir(&tmp).unwrap().collect();
    assert!(leaked.is_empty(), "{}: temp workspace leaked", sc.id);
    let _ = std::fs::remove_dir_all(&root);

    assert_eq!(sep, case.separator_pages, "{}: separator pages", sc.id);
    assert_eq!(parts, case.parts, "{}: parts", sc.id);
    assert_eq!(bodies, case.part_bodies, "{}: part bodies", sc.id);
    assert_eq!(error, case.error, "{}: error", sc.id);
    assert_eq!(transcript, case.transcript, "{}: tool transcript", sc.id);
    assert_eq!(leftovers, case.leftovers, "{}: output dir", sc.id);
    assert!(case.asns.is_empty() && case.errors.is_empty());
    transcript
}

fn tempdir() -> std::path::PathBuf {
    static ORIGINAL: std::sync::OnceLock<std::path::PathBuf> = std::sync::OnceLock::new();
    let original = ORIGINAL.get_or_init(std::env::temp_dir);
    let base = original.join(format!(
        "barcode-contract-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    std::fs::create_dir_all(&base).unwrap();
    base
}

#[test]
fn split_and_scan_scenarios_match_go() {
    let f = fixture();
    assert!(f.split.len() >= 28, "scenarios shrank: {}", f.split.len());
    // Keep the original TMPDIR for the scratch roots.
    let mut seen_error = 0;
    let mut seen_parts = 0;
    for case in &f.split {
        if !case.error.is_empty() {
            seen_error += 1;
        }
        if !case.parts.is_empty() {
            seen_parts += 1;
        }
        run(&f, case);
    }
    assert!(
        seen_error >= 8 && seen_parts >= 15,
        "{seen_error} {seen_parts}"
    );
}

#[test]
fn split_negative_control_a_changed_transcript_is_caught() {
    let f = fixture();
    let case = f
        .split
        .iter()
        .find(|c| c.scenario.id == "discard-sep-page2-of-4")
        .unwrap();
    let transcript = run(&f, case);
    assert_eq!(transcript.len(), 6, "{transcript:?}");
    assert!(transcript[0].starts_with("P\u{1f}-png\u{1f}-r\u{1f}300\u{1f}$DIR/in.pdf"));
    assert!(transcript[1].starts_with("Q\u{1f}--show-npages"));
    assert!(
        transcript[2].contains("--empty\u{1f}--pages")
            && transcript[2].contains("\u{1f}1-1\u{1f}--")
    );
    // A tampered Go expectation must make the replay fail.
    let mut mutated = case.clone();
    mutated.transcript[0] = mutated.transcript[0].replace("300", "150");
    assert!(std::panic::catch_unwind(|| run(&f, &mutated)).is_err());
    let mut mutated = case.clone();
    mutated.parts.pop();
    assert!(std::panic::catch_unwind(|| run(&f, &mutated)).is_err());
    let mut mutated = case.clone();
    mutated.separator_pages = vec![3];
    assert!(std::panic::catch_unwind(|| run(&f, &mutated)).is_err());
}
